            l.starts_with(&format!("{},", name)) || l.split(',').next() == Some(name)
        });
        assert!(present, "components.csv missing fully-qualified row '{}'", name);
    }
    // Bare short names from iter4 must be absent as component names.
    for bare in [
        "personas",
        "research",
        "phases",
        "installer",
        "git-hook",
        "verification-config",
        "analysis",
        "tag-scan",
        "force-schema",
