//! Storage.Config — THE config (v3 TOML): app + verify policy keys.
//!
//! Owns format_version, change_detection, AND verification policy
//! (super_strict, token_warn). There is no verification-config module.

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};

fn default_format_version() -> String {
    "v3".to_string()
}
fn default_change_detection() -> bool {
    true
}
fn default_super_strict() -> bool {
    true
}
fn default_token_warn() -> usize {
    1000
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StorageConfig {
    #[serde(default = "default_format_version")]
    pub format_version: String,
    #[serde(default = "default_change_detection")]
    pub change_detection: bool,
    #[serde(default = "default_super_strict")]
    pub super_strict: bool,
    #[serde(default = "default_token_warn")]
    pub token_warn: usize,
}

impl Default for StorageConfig {
    fn default() -> Self {
        Self {
            format_version: default_format_version(),
            change_detection: default_change_detection(),
            super_strict: default_super_strict(),
            token_warn: default_token_warn(),
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct V3Document {
    #[serde(default = "default_format_version")]
    format_version: String,
    #[serde(default)]
    storage: StorageSection,
    #[serde(default)]
    verification: VerificationSection,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize)]
struct StorageSection {
    #[serde(default = "default_change_detection")]
    change_detection: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct VerificationSection {
    #[serde(default = "default_super_strict")]
    super_strict: bool,
    #[serde(default = "default_token_warn")]
    token_warn: usize,
}

impl Default for VerificationSection {
    fn default() -> Self {
        Self {
            super_strict: default_super_strict(),
            token_warn: default_token_warn(),
        }
    }
}

/// Parse a v3 TOML document. App keys and verify-policy keys both land here.
pub fn parse_v3(toml_str: &str) -> Result<StorageConfig> {
    let doc: V3Document = toml::from_str(toml_str).with_context(|| "parse storage v3 TOML")?;
    Ok(StorageConfig {
        format_version: doc.format_version,
        change_detection: doc.storage.change_detection,
        super_strict: doc.verification.super_strict,
        token_warn: doc.verification.token_warn,
    })
}

/// Render the full v3 document (storage + verify policy sections).
pub fn render_v3(cfg: &StorageConfig) -> String {
    format!(
        "# residual v3 configuration\nformat_version = \"{}\"\n\n[storage]\nchange_detection = {}\n\n[verification]\nsuper_strict = {}\ntoken_warn = {}\n",
        cfg.format_version, cfg.change_detection, cfg.super_strict, cfg.token_warn
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn storage_config_parses_v3_toml() {
        let raw = r#"
format_version = "v3"

[storage]
change_detection = false

[verification]
super_strict = false
token_warn = 42
"#;
        let cfg = parse_v3(raw).unwrap();
        assert_eq!(cfg.format_version, "v3");
        assert!(!cfg.change_detection);
        assert!(!cfg.super_strict);
        assert_eq!(cfg.token_warn, 42);
    }

    #[test]
    fn verification_reads_policy_from_storage_config() {
        let raw = r#"
format_version = "v3"
[storage]
change_detection = true
[verification]
super_strict = true
token_warn = 777
"#;
        let cfg = parse_v3(raw).unwrap();
        // Verification consumes these fields from storage-config — no separate module.
        assert!(cfg.super_strict);
        assert_eq!(cfg.token_warn, 777);
        let rendered = render_v3(&cfg);
        assert!(rendered.contains("super_strict"));
        assert!(rendered.contains("token_warn"));
        assert!(rendered.contains("[storage]"));
    }
}

//! Migration — naive → v3 only for now.
//! Policy keys migrate into storage-config (no verification-config module).

use anyhow::{Context, Result};
use serde::Deserialize;

use crate::storage::config::StorageConfig;

#[derive(Debug, Clone)]
pub struct MigratedV3 {
    pub format_version: String,
    pub storage: StorageConfig,
    pub toml: String,
}

#[derive(Debug, Deserialize)]
struct NaiveDocument {
    #[serde(default)]
    validation: NaiveValidation,
    #[serde(default)]
    skills: NaiveSkills,
}

#[derive(Debug, Default, Deserialize)]
struct NaiveValidation {
    #[serde(default = "default_true")]
    strict: bool,
}

#[derive(Debug, Default, Deserialize)]
struct NaiveSkills {
    #[serde(default = "default_token_warn")]
    token_warn: usize,
}

fn default_true() -> bool {
    true
}
fn default_token_warn() -> usize {
    1000
}

/// Convert naive config.toml (`[validation]` / `[skills]`) into v3 TOML.
pub fn migrate_naive_to_v3(naive_toml: &str) -> Result<MigratedV3> {
    let naive: NaiveDocument =
        toml::from_str(naive_toml).with_context(|| "parse naive config.toml")?;
    let storage = StorageConfig {
        format_version: "v3".to_string(),
        change_detection: true,
        super_strict: naive.validation.strict,
        token_warn: naive.skills.token_warn,
    };
    let toml_out = crate::storage::config::render_v3(&storage);
    Ok(MigratedV3 {
        format_version: storage.format_version.clone(),
        storage,
        toml: format!(
            "# residual v3 configuration (migrated from naive)\n{}",
            toml_out.trim_start_matches("# residual v3 configuration\n")
        ),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn migration_naive_to_v3() {
        let naive = "[validation]\nstrict = false\n\n[skills]\ntoken_warn = 500\n";
        let v3 = migrate_naive_to_v3(naive).unwrap();
        assert_eq!(v3.format_version, "v3");
        assert!(v3.storage.change_detection);
        assert!(!v3.storage.super_strict);
        assert_eq!(v3.storage.token_warn, 500);
        assert!(v3.toml.contains("format_version = \"v3\""));
        assert!(v3.toml.contains("[storage]"));
        assert!(v3.toml.contains("[verification]"));
        assert!(v3.toml.contains("super_strict = false"));
        assert!(v3.toml.contains("token_warn = 500"));
    }
}

//! Verification — criticality, link + lexicon continuity, one-way tags,
//! personas adequacy (min:2 until alpha/beta exist).
//!
//! Policy (super_strict, token_warn) is read from storage-config.
//! There is no verification-config / verification/config.rs module.

use anyhow::{bail, Result};
use std::collections::HashSet;
use std::path::Path;

use crate::cli::VerifyCheck;
use crate::config::Config;
use crate::storage::config::{self as storage_config, StorageConfig};

pub mod git_hook;

#[allow(unused_imports)]
pub use crate::verify::{
    check_links, check_traits, parse_trait, trait_uses_terminology, LinkViolation, TraitParts,
    TraitViolation,
};

pub fn run(cfg: &Config, check: VerifyCheck) -> Result<()> {
    crate::verify::run(cfg, check)
}

/// Load verification policy from storage-config (v3 TOML on disk, or defaults).
pub fn policy_from_storage_config(residual_dir: &Path) -> Result<StorageConfig> {
    let path = residual_dir.join("config.toml");
    if !path.exists() {
        return Ok(StorageConfig::default());
    }
    let raw = std::fs::read_to_string(&path)?;
    if raw.contains("format_version") || raw.contains("[verification]") || raw.contains("[storage]")
    {
        storage_config::parse_v3(&raw)
    } else {
        // Naive config: map validation.strict / skills.token_warn.
        let migrated = crate::storage::integrity::migration::migrate_naive_to_v3(&raw)?;
        Ok(migrated.storage)
    }
}

/// One-way tag rule: metadata MAY exist without codebase tags;
/// if tagged in code, MUST exist in metadata.
pub fn check_one_way_tags<S, T>(metadata_ids: &[S], tagged_ids: &[T]) -> Result<()>
where
    S: AsRef<str>,
    T: AsRef<str>,
{
    let meta: HashSet<String> = metadata_ids
        .iter()
        .map(|s| s.as_ref().to_string())
        .collect();
    let mut missing = Vec::new();
    for id in tagged_ids {
        let id = id.as_ref();
        if !meta.contains(id) {
            missing.push(id.to_string());
        }
    }
    if missing.is_empty() {
        Ok(())
    } else {
        bail!(
            "tagged in code but missing from metadata: {}",
            missing.join(", ")
        )
    }
}

/// Until longitudinal alpha/beta exist, walks/sessions require min:2 personas
/// (stakeholder + direct user). Personas module stores; Verification checks.
pub fn check_personas_adequacy<S: AsRef<str>>(names: &[S]) -> Result<()> {
    if names.len() < 2 {
        bail!(
            "verification requires at least 2 personas (stakeholder + direct user) until alpha/beta exist; found {}",
            names.len()
        );
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn verification_allows_metadata_without_tags_but_not_tags_without_metadata() {
        let meta = ["S-01", "S-02"];
        let none: [&str; 0] = [];
        assert!(
            check_one_way_tags(&meta, &none).is_ok(),
            "metadata-only ids are allowed"
        );
        assert!(
            check_one_way_tags(&meta, &["S-01"]).is_ok(),
            "tagged ids that exist in metadata are allowed"
        );
        let err = check_one_way_tags(&meta, &["S-99"]).unwrap_err();
        assert!(
            err.to_string().contains("S-99"),
            "code tags without metadata must fail, got {err}"
        );
    }

    #[test]
    fn verification_requires_min_two_personas() {
        let empty: [&str; 0] = [];
        assert!(check_personas_adequacy(&empty).is_err());
        assert!(check_personas_adequacy(&["alice"]).is_err());
        assert!(check_personas_adequacy(&["alice", "bob"]).is_ok());
    }

    #[test]
    fn verification_reads_policy_from_storage_config() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();
        std::fs::write(
            residual.join("config.toml"),
            r#"
format_version = "v3"
[storage]
change_detection = true
[verification]
super_strict = false
token_warn = 321
"#,
        )
        .unwrap();
        let policy = policy_from_storage_config(&residual).unwrap();
        assert!(!policy.super_strict);
        assert_eq!(policy.token_warn, 321);
        assert!(
            !std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("src/verification/config.rs")
                .exists(),
            "verification-config module must not exist"
        );
    }
}

//! Force schema — 1/2 of a residue (the purpose/stressor inside it).
//!
//! A force carries naive_change + outcomes + shortname. It does **not** carry
//! traits or component lists; component mapping lives on Residue.

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ForceKind {
    Purpose,
    Stressor,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Force {
    pub id: String,
    pub kind: ForceKind,
    pub shortname: String,
    pub naive_change: String,
    pub outcomes: Vec<String>,
    pub description: String,
    pub attractor_id: String,
}

impl Force {
    pub fn purpose(
        id: impl Into<String>,
        shortname: impl Into<String>,
        naive_change: impl Into<String>,
        outcomes: Vec<String>,
    ) -> Self {
        Self {
            id: id.into(),
            kind: ForceKind::Purpose,
            shortname: shortname.into(),
            naive_change: naive_change.into(),
            outcomes,
            description: String::new(),
            attractor_id: String::new(),
        }
    }

    pub fn stressor(
        id: impl Into<String>,
        shortname: impl Into<String>,
        naive_change: impl Into<String>,
        outcomes: Vec<String>,
    ) -> Self {
        Self {
            id: id.into(),
            kind: ForceKind::Stressor,
            shortname: shortname.into(),
            naive_change: naive_change.into(),
            outcomes,
            description: String::new(),
            attractor_id: String::new(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::structure::analysis::residues::Residue;

    #[test]
    fn force_is_half_of_residue() {
        let force = Force::purpose(
            "P-01",
            "auth-hub",
            "add auth without rewriting the hub",
            vec!["operator authenticates via residue mapping".into()],
        );
        let residue = Residue {
            id: "R-01".into(),
            force_id: force.id.clone(),
            component_id: "cli".into(),
            status: "proposed".into(),
            notes: String::new(),
        };
        assert_eq!(residue.force_id, force.id, "residue maps a force id");
        assert!(!residue.component_id.is_empty(), "residue maps a component id");
        assert_ne!(
            residue.force_id, residue.component_id,
            "force half and component half are distinct"
        );
        assert!(
            !force.outcomes.is_empty(),
            "force carries outcomes (the narrative half)"
        );
        let debug = format!("{:?}", force);
        assert!(
            !debug.to_lowercase().contains("trait"),
            "Force must not carry traits, got {debug}"
        );
        assert!(
            !debug.to_lowercase().contains("component"),
            "Force must not carry component lists, got {debug}"
        );
    }
}

//! Purposes schema — Force specialization (naive_change + outcomes, not traits).

use super::force::{Force, ForceKind};

#[derive(Debug, Clone, PartialEq, Eq)]
